#include <stdio.h>
#include <stdlib.h>

int main(int argc, char **argv) {
    if (argc < 3) {
        printf("Usage: %s <num_nodes> <edges>\n", argv[0]);
        return 1;
    }

    int num_nodes = atoi(argv[1]);
    int num_edges = argc - 2;
    int edges[num_edges][2];

    for (int i = 0; i < num_edges; i++) {
        edges[i][0] = atoi(argv[i + 2]);
        edges[i][1] = atoi(argv[i + 3]);
    }

    // Initialize visited and queue arrays
    int visited[num_nodes];
    int queue[num_nodes];
    for (int i = 0; i < num_nodes; i++) {
        visited[i] = 0;
        queue[i] = 0;
    }

    // Initialize adjacency matrix
    int adj[num_nodes][num_nodes];
    for (int i = 0; i < num_nodes; i++) {
        for (int j = 0; j < num_nodes; j++) {
            adj[i][j] = 0;
        }
    }

    // Populate adjacency matrix
    for (int i = 0; i < num_edges; i++) {
        adj[edges[i][0]][edges[i][1]] = 1;
        adj[edges[i][1]][edges[i][0]] = 1;
    }

    // Perform BFS traversal
    for (int i = 0; i < num_nodes; i++) {
        if (!visited[i]) {
            printf("%d: ", i);
            queue[0] = i;
            visited[i] = 1;
            int front = 0;
            int rear = 1;

            while (front < rear) {
                int node = queue[front];
                front++;

                for (int j = 0; j < num_nodes; j++) {
                    if (adj[node][j] && !visited[j]) {
                        queue[rear] = j;
                        visited[j] = 1;
                        rear++;
                        printf("%d ", j);
                    }
                }
            }
            printf("\n");
        }
    }

    return 0;
}
